"""Storage provider interface. Keys are generated by the server only."""

from __future__ import annotations

import re
from abc import ABC
from abc import abstractmethod
from typing import BinaryIO

# Keys look like "incoming/<uuid>" or "variants/<uuid>/small-<hash>.webp".
_KEY_RE = re.compile(r"^[a-z0-9][a-z0-9_-]*(/[a-z0-9][a-z0-9_.-]*){0,4}$")


class InvalidStorageKey(ValueError):
    pass


def validate_key(key: str) -> str:
    """
    Reject anything that is not a server generated key: absolute paths,
    "..", backslashes, NUL, upper case, unexpected characters.
    """
    if (
        not isinstance(key, str)
        or len(key) > 255
        or ".." in key
        or not _KEY_RE.fullmatch(key)
    ):
        raise InvalidStorageKey("Invalid storage key")
    return key


class StorageProvider(ABC):
    """Minimal blob store used by the image pipeline."""

    @abstractmethod
    def save(self, key: str, fileobj: BinaryIO, content_type: str) -> int:
        """Store the stream under ``key``; returns the number of bytes."""

    @abstractmethod
    def open(self, key: str) -> BinaryIO:
        """Readable, seekable binary file object. Caller closes it."""

    @abstractmethod
    def delete(self, key: str) -> None:
        """Idempotent: deleting a missing key is not an error."""

    @abstractmethod
    def exists(self, key: str) -> bool: ...

    @abstractmethod
    def size(self, key: str) -> int: ...

    def x_accel_path(self, key: str) -> str | None:
        """Internal Nginx location for X-Accel-Redirect, if configured."""
        return None
